  console.log(`${s.id}: start ${(s.start / 1000).toFixed(1)}s, audio ${(s.duration / 1000).toFixed(1)}s, took ${((Date.now() - t0 - s.start) / 1000).toFixed(1)}s`);
}
await sleep(1500);
const video = await page.video().path();
await ctx.close();
await browser.close();
stopServer();

// ---------- merge ----------
const inputs = ["-i", video];
const filters = [];
segments.forEach((s, i) => {
  inputs.push("-i", s.audio);
  const ms = Math.round(s.start + 300);
  filters.push(`[${i + 1}:a]aresample=48000,adelay=${ms}|${ms}[a${i}]`);
