  { id: "edge2_log",
    say: "Here is the server log for that request. The mock model returned malformed output on its first attempt. The schema check rejected it, and logged only the names of the failing fields. The app retried once, and only the valid result was saved. If both attempts fail, nothing is stored, and the user sees an error.",
    act: async () => {
      const lines = serverLog.split("\n").filter((l) => /POST \/w\/.*\/p\/|summarizeProject|Summary attempt/.test(l)).slice(-3);
      await terminal("npm run dev — server log", [
        { cmd: "# server output while “Summarize vehicle” ran", out: lines.join("\n") || "(no log captured)", color: "#ffcb6b" },
      ]);
    } },
  { id: "tests",
    say: "Finally, n p m test. Sixteen tests run against the local database. They cover isolation at the URL, request body, and database layers, the viewer, editor and owner roles, and the summary validation, including the prompt injection note.",
    act: async () => {
      let out;
      try { out = execFileSync("npm", ["test"], { cwd: APP, env: { ...process.env, FORCE_COLOR: "0", NO_COLOR: "1" } }).toString(); }
      catch (e) { out = (e.stdout?.toString() ?? "") + (e.stderr?.toString() ?? ""); }
      out = strip(out).split("\n").filter((l) => l.trim() && !/injected env|^>/.test(l)).join("\n");
      await terminal("npm test", [{ cmd: "npm test", out, color: "#addb67" }]);
    } },
  { id: "close",
    say: "That covers the app and both edge cases. The README explains how to run it, the main design decisions and trade offs, and the next steps, such as email invitations with expiring tokens, audit logging, rate limits, and a real model provider behind the same interface. Thank you for watching.",
    act: async () => card(`<div style="max-width:760px;padding:24px">
      <div style="letter-spacing:.14em;font-size:13px;font-weight:700;color:#13644b">SUMMARY</div>
      <h1 style="font-size:40px;margin:12px 0 22px;letter-spacing:-.02em">Fleet Workspace</h1>
      <ul style="font-size:19px;line-height:1.9;color:#2b3a34;padding-left:22px;margin:0 0 24px">
        <li>Isolation enforced in PostgreSQL: RLS enabled + forced, deny by default</li>
        <li>Server verifies the user; client IDs are never trusted</li>
        <li>Forged URL, body and direct DB calls: same response as a missing ID</li>
        <li>Summaries: untrusted input, schema-validated, one retry, never stored invalid</li>
      </ul>
      <p style="font-size:15px;color:#74817b">Run instructions, design decisions, trade-offs and next steps: README.md</p></div>`) },
];

// ---------- audio ----------
for (const s of segments) {
  const file = path.join(OUT, "audio", `${s.id}.aiff`);
  execFileSync("say", ["-v", "Rishi", "-r", "172", "-o", file, s.say]);
  s.audio = file;
  s.duration = Number(execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", file]).toString()) * 1000;
}

// ---------- record ----------
for (const s of segments) {
  s.start = Date.now() - t0;
  const audioDone = sleep(s.duration);
  await s.act();
  await audioDone;
  await sleep(700);
  console.log(`${s.id}: start ${(s.start / 1000).toFixed(1)}s, audio ${(s.duration / 1000).toFixed(1)}s, took ${((Date.now() - t0 - s.start) / 1000).toFixed(1)}s`);
}
await sleep(1500);
const video = await page.video().path();
await ctx.close();
await browser.close();
stopServer();

// ---------- merge ----------
const inputs = ["-i", video];
const filters = [];
segments.forEach((s, i) => {
  inputs.push("-i", s.audio);
  const ms = Math.round(s.start + 300);
  filters.push(`[${i + 1}:a]aresample=48000,adelay=${ms}|${ms}[a${i}]`);
});
const mix = `${filters.join(";")};${segments.map((_, i) => `[a${i}]`).join("")}amix=inputs=${segments.length}:normalize=0[aout]`;
const final = path.join(OUT, "fleet-workspace-demo.mp4");
execFileSync("ffmpeg", ["-y", ...inputs, "-filter_complex", mix, "-map", "0:v", "-map", "[aout]",
  "-c:v", "libx264", "-preset", "medium", "-crf", "20", "-pix_fmt", "yuv420p", "-r", "25",
  "-c:a", "aac", "-b:a", "160k", "-movflags", "+faststart", final], { stdio: "inherit" });
console.log("DONE", final);
process.exit(0);

