const fresh = new Set(["intro", "login", "signin_editor", "edge1_url_real", "edge1_url_missing",
  "edge1_body_real", "edge1_db", "rls_sql", "edge2_note", "prompt", "edge2_log", "tests", "close"]);
const ffprobeDuration = (f) => Number(execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).toString());
let lastUrl = null;
for (const s of segments) {
  page = await ctx.newPage();
  const created = Date.now();
  if (!fresh.has(s.id) && lastUrl) { await page.goto(lastUrl); await settle(page); }
  s.offset = Date.now() - created;
  const audioDone = sleep(s.duration);
  await s.act();
  await audioDone;
  await sleep(700);
  s.wall = Date.now() - created;
  if (page.url().startsWith("http")) lastUrl = page.url();
  const video = page.video();
  await page.close();
  s.video = await video.path();
  console.log(`${s.id}: lead-in ${(s.offset / 1000).toFixed(1)}s, audio ${(s.duration / 1000).toFixed(1)}s, clip ${(s.wall / 1000).toFixed(1)}s`);
}
await ctx.close();
await browser.close();
stopServer();

// ---------- merge: stretch each clip to its real duration, add its narration, then join ----------
const parts = [];
for (const [i, s] of segments.entries()) {
  const wall = s.wall / 1000;
  const factor = wall / ffprobeDuration(s.video);
  const delay = Math.round(s.offset + 250);
  const part = path.join(OUT, `part-${String(i).padStart(2, "0")}.mp4`);
  execFileSync("ffmpeg", ["-v", "error", "-y", "-i", s.video, "-i", s.audio, "-filter_complex",
    `[0:v]setpts=PTS*${factor.toFixed(5)},scale=1280:800:flags=lanczos,fps=25,format=yuv420p[v];` +
    `[1:a]aresample=48000,adelay=${delay}|${delay},apad[a]`,
    "-map", "[v]", "-map", "[a]", "-t", wall.toFixed(3),
    "-c:v", "libx264", "-preset", "medium", "-crf", "20", "-c:a", "aac", "-b:a", "160k", "-ar", "48000", "-ac", "2", part]);
  parts.push(part);
  console.log(`${s.id}: stretch x${factor.toFixed(3)}`);
}
const list = path.join(OUT, "parts.txt");
fs.writeFileSync(list, parts.map((f) => `file '${f}'`).join("\n"));
const final = path.join(OUT, "fleet-workspace-demo.mp4");
execFileSync("ffmpeg", ["-v", "error", "-y", "-f", "concat", "-safe", "0", "-i", list, "-c", "copy", "-movflags", "+faststart", final]);
console.log("DONE", final, ffprobeDuration(final).toFixed(1) + "s");
process.exit(0);
'''
open(p,"w").write(s)
EOF
node --check record.mjs && echo syntax-ok

