// Records the demo with sentence-level sync. Each segment is its own clip;
// every narration sentence (pre-generated and whisper-verified by voice.py)
// is placed at the moment the script reaches it, so the voice never talks
// about a page that is still loading. Loading before a segment's first
// sentence is trimmed out of the clip.
import { chromium } from "playwright-core";
import { execFileSync, spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const APP = "/Users/chakrapanireddy/Documents/My Projects/fleet-workspace-app";
const HERE = path.dirname(new URL(import.meta.url).pathname);
const OUT = path.join(HERE, "out2");
const BASE = "http://localhost:3000";
const PASSWORD = "FleetDemo2026!";
const DECCAN = "20000000-0000-4000-8000-000000000001";
const CHARMINAR = "20000000-0000-4000-8000-000000000002";
const MISSING = "99999999-9999-4999-8999-999999999999";
const TATA = "30000000-0000-4000-8000-000000000001";
fs.rmSync(OUT, { recursive: true, force: true });
fs.mkdirSync(OUT, { recursive: true });

const manifest = JSON.parse(fs.readFileSync(path.join(HERE, "voice", "manifest.json"), "utf8"));
const env = Object.fromEntries(
  fs.readFileSync(path.join(APP, ".env.local"), "utf8").trim().split("\n")
    .map((l) => [l.slice(0, l.indexOf("=")), l.slice(l.indexOf("=") + 1).replace(/^"(.*)"$/, "$1")]),
);
const strip = (s) => s.replace(/\x1b\[[0-9;]*m/g, "");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const sh = (cmd) => strip(execFileSync("bash", ["-lc", cmd], { cwd: APP }).toString()).trimEnd();
const ffprobeDuration = (f) => Number(execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).toString());

// ---------- dev server ----------
let serverLog = "";
const server = spawn("npm", ["run", "dev"], { cwd: APP, detached: true, env: { ...process.env, FORCE_COLOR: "0" } });
server.stdout.on("data", (d) => (serverLog += strip(d.toString())));
server.stderr.on("data", (d) => (serverLog += strip(d.toString())));
const stopServer = () => { try { process.kill(-server.pid); } catch {} };
process.on("exit", stopServer);
for (let i = 0; i < 60 && !serverLog.includes("Ready"); i++) await sleep(500);
if (!serverLog.includes("Ready")) throw new Error("dev server did not start:\n" + serverLog);

const browser = await chromium.launch({ channel: "chrome", headless: true });
const settle = async (pg) => { await pg.waitForLoadState("load"); await sleep(700); };

// warm-up (compiles routes, outside the recording)
{
  const c = await browser.newContext();
  const p = await c.newPage();
  await p.goto(`${BASE}/login`); await settle(p);
  await p.fill("input[name=email]", "owner@fleet.test");
  await p.fill("input[name=password]", PASSWORD);
  await p.click("button:has-text('Sign in')"); await p.waitForURL(`${BASE}/`);
  for (const u of [`/w/${DECCAN}`, `/w/${DECCAN}/p/${TATA}`, `/w/${MISSING}`]) { await p.goto(BASE + u); await settle(p); }
  await c.close();
}

const ctx = await browser.newContext({
  viewport: { width: 1152, height: 720 },
  recordVideo: { dir: OUT, size: { width: 1152, height: 720 } },
});
await ctx.addInitScript(() => {
  const render = () => {
    const text = sessionStorage.getItem("demo-caption");
    let el = document.getElementById("demo-caption");
    if (!text) { el?.remove(); return; }
    if (!el) {
      el = document.createElement("div");
      el.id = "demo-caption";
      el.style.cssText = "position:fixed;left:50%;bottom:22px;transform:translateX(-50%);max-width:1060px;z-index:2147483647;background:rgba(17,24,39,.92);color:#fff;font:600 17px/1.45 -apple-system,Helvetica,Arial,sans-serif;padding:11px 18px;border-radius:10px;box-shadow:0 8px 30px rgba(0,0,0,.25);white-space:pre-wrap;text-align:center";
      document.documentElement.appendChild(el);
    }
    el.textContent = text;
  };
  window.__renderCaption = render;
  document.addEventListener("DOMContentLoaded", render);
});

// ---------- page helpers ----------
let page;
async function caption(text) {
  await page.evaluate((t) => {
    if (t) sessionStorage.setItem("demo-caption", t); else sessionStorage.removeItem("demo-caption");
    window.__renderCaption?.();
  }, text ?? "").catch(() => {});
}
async function highlight(locator, ms = 1600) {
  locator = locator.first();
  await locator.scrollIntoViewIfNeeded().catch(() => {});
  await locator.evaluate((el, ms) => {
    const prev = [el.style.outline, el.style.outlineOffset];
    el.style.outline = "4px solid #f59e0b"; el.style.outlineOffset = "4px";
    setTimeout(() => { [el.style.outline, el.style.outlineOffset] = prev; }, ms);
  }, ms);
  await sleep(350);
}
async function clickOn(locator) { await highlight(locator, 900); await locator.first().click(); }
async function type(locator, text) { locator = locator.first(); await highlight(locator, 700); await locator.fill(""); await locator.pressSequentially(text, { delay: 40 }); }
async function goto(url) { await page.goto(url); await settle(page); }
async function signIn(email) {
  await goto(`${BASE}/login`);
  await type(page.locator("input[name=email]"), email);
  await type(page.locator("input[name=password]"), PASSWORD);
  await clickOn(page.locator("button:has-text('Sign in')"));
  await page.waitForURL(`${BASE}/`); await settle(page);
}
async function signOut() {
  await clickOn(page.locator("button:has-text('Sign out')"));
  await page.waitForURL(/\/login/); await settle(page);
}
async function card(html) {
  await page.goto("about:blank");
  await page.setContent(`<html><body style="margin:0;height:100vh;display:grid;place-items:center;background:#f5f7f5;font-family:-apple-system,Helvetica,Arial,sans-serif;color:#17231f">${html}</body></html>`);
  await sleep(300);
}
// A terminal page whose blocks are added on cue from the script.
async function terminal(title) {
  await page.goto("about:blank");
  await page.setContent(`<html><body style="margin:0;background:#0f1419;color:#d6deeb;font:15px/1.5 Menlo,Monaco,monospace">
  <div style="background:#1f2630;padding:9px 16px;color:#9aa5b1;font:13px -apple-system,Helvetica,sans-serif;display:flex;gap:8px;align-items:center">
  <span style="width:12px;height:12px;border-radius:50%;background:#ff5f57;display:inline-block"></span><span style="width:12px;height:12px;border-radius:50%;background:#febc2e;display:inline-block"></span><span style="width:12px;height:12px;border-radius:50%;background:#28c840;display:inline-block"></span>
  <span style="margin-left:10px">${title.replaceAll("<", "&lt;")}</span></div>
  <pre id="t" style="margin:0;padding:18px 22px;white-space:pre-wrap;word-break:break-all"></pre>
  <script>
    const t = document.getElementById("t");
    const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    window.addBlock = async (b) => {
      const p = document.createElement("span"); p.style.color = "#7fdbca"; p.textContent = "$ "; t.appendChild(p);
      const c = document.createElement("span"); c.style.color = "#ffffff"; t.appendChild(c);
      for (const ch of b.cmd) { c.textContent += ch; await sleep(b.cmd.length > 100 ? 5 : 16); }
      await sleep(300);
      const o = document.createElement("span"); o.style.color = b.color || "#d6deeb"; o.textContent = "\\n" + b.out + "\\n\\n"; t.appendChild(o);
      window.scrollTo(0, document.body.scrollHeight);
    };
  </script></body></html>`);
  await sleep(300);
}
const block = (b) => page.evaluate((b) => window.addBlock(b), b);

// ---------- narration cues ----------
let clip;
function line(k) {
  const l = clip.lines[k];
  if (!l) throw new Error(`segment ${clip.id} has no line ${k}`);
  if (l.at !== undefined) throw new Error(`line ${k} of ${clip.id} spoken twice`);
  l.at = Date.now() - clip.created;
  const gap = /[?]$/.test(l.text) ? 420 : /\.\.\./.test(l.text) ? 500 : 300;
  return sleep(l.duration * 1000 + gap);
}
const both = (...ps) => Promise.all(ps);

// ---------- segments (order matches the script sections) ----------
const vehicleForm = () => page.locator(".side-column form:has(input[name=registration])");
const segments = [
  { id: "intro", act: async () => {
    await card(`<div style="text-align:center;max-width:820px;padding:24px">
      <div style="width:64px;height:64px;margin:0 auto 22px;border-radius:14px;background:#13644b;color:#fff;display:grid;place-items:center;font:700 34px Arial">F</div>
      <div style="letter-spacing:.14em;font-size:13px;font-weight:700;color:#13644b">TECHNICAL ASSESSMENT DEMO</div>
      <h1 style="font-size:52px;margin:14px 0 10px;letter-spacing:-.03em">Fleet Workspace</h1>
      <p style="font-size:20px;color:#4b5a54;margin:0 0 28px">Multi-tenant workspaces · projects · notes, with row-level security</p>
      <p style="font-size:15px;color:#74817b">Next.js · TypeScript · Supabase (PostgreSQL + Auth)</p></div>`);
    for (let k = 0; k < 4; k++) await line(k);
  } },
  { id: "login", act: async () => {
    await goto(`${BASE}/login`);
    await caption("Workspace = fleet company   ·   Project = vehicle   ·   Note = vehicle note");
    for (let k = 0; k < 10; k++) await line(k);
  } },
  { id: "signin_editor", act: async () => {
    await goto(`${BASE}/login`);
    await both(line(0), (async () => {
      await type(page.locator("input[name=email]"), "editor@fleet.test");
      await type(page.locator("input[name=password]"), PASSWORD);
    })());
    await clickOn(page.locator("button:has-text('Sign in')"));
    await page.waitForURL(`${BASE}/`); await settle(page);
    await caption("Same user, different role per workspace");
    await line(1);
    await both(line(2), highlight(page.locator("a:has-text('Charminar Cabs')"), 2500));
    await both(line(3), highlight(page.locator("a:has-text('Deccan Logistics')"), 2500));
    await line(4); await line(5); await line(6);
  } },
  { id: "switch_owner", act: async () => {
    await caption("");
    await both(line(0), (async () => {
      await clickOn(page.locator("a:has-text('Charminar Cabs')"));
      await page.waitForURL(new RegExp(CHARMINAR)); await settle(page);
    })());
    await both(line(1), highlight(page.locator("text=Manage access"), 2500));
    await both(line(2), highlight(page.locator(".member-heading"), 2500));
    await line(3); await line(4);
  } },
  { id: "switch_editor", act: async () => {
    await both(line(0), highlight(page.locator(".workspace-links"), 2000));
    await both(line(1), (async () => {
      await clickOn(page.locator(".workspace-links a:has-text('Deccan Logistics')"));
      await page.waitForURL(new RegExp(DECCAN)); await settle(page);
    })());
    await both(line(2), highlight(page.locator(".user-role"), 2500));
  } },
  { id: "create_vehicle", act: async () => {
    await both(line(0), highlight(vehicleForm(), 1500));
    await both(line(1), (async () => {
      await type(vehicleForm().locator("input[name=name]"), "Ashok Leyland Dost");
      await type(vehicleForm().locator("input[name=registration]"), "TS08 EX 7788");
    })());
    await both(line(2), (async () => {
      await clickOn(vehicleForm().locator("button[type=submit]"));
      await page.locator(".vehicle-card:has-text('Ashok Leyland Dost')").waitFor();
    })());
    await both(line(3), highlight(page.locator(".vehicle-card:has-text('Ashok Leyland Dost')"), 2000));
    await line(4);
  } },
  { id: "edit_vehicle", act: async () => {
    const c = page.locator(".vehicle-card:has-text('Ashok Leyland Dost')");
    await both(line(0), clickOn(c.locator("summary:has-text('Edit vehicle')")));
    await both(line(1), (async () => {
      await highlight(c.locator("select[name=status]"), 800);
      await c.locator("select[name=status]").selectOption("maintenance");
      await clickOn(c.locator("button:has-text('Save changes')"));
      await page.locator(".vehicle-card:has-text('Ashok Leyland Dost') .status-label.maintenance").waitFor();
    })());
    await c.locator("summary:has-text('Edit vehicle')").click();
    await highlight(page.locator(".vehicle-card:has-text('Ashok Leyland Dost')"), 1200);
  } },
  { id: "notes", act: async () => {
    await both(line(0), (async () => {
      await clickOn(page.locator(".vehicle-card:has-text('Ashok Leyland Dost') a.vehicle-link"));
      await page.waitForURL(/\/p\//); await settle(page);
    })());
    const create = page.locator("form:has(button:has-text('Add note'))");
    await both(line(1), type(create.locator("textarea"), "Clutch feels heavy. Book a service this week."));
    await clickOn(create.locator("button:has-text('Add note')"));
    await page.locator("text=Clutch feels heavy").first().waitFor();
    const edit = page.locator("form:has(button:has-text('Save note'))").first();
