    await page.locator("text=Service booked for Friday").first().waitFor();
    await both(line(3), highlight(page.locator("text=Service booked for Friday"), 1800));
    await line(4); await line(5);
  } },
  { id: "viewer", act: async () => {
    await line(0);
    await both(line(1), (async () => { await signOut(); await signIn("viewer@fleet.test"); })());
    await clickOn(page.locator("a:has-text('Deccan Logistics')"));
    await page.waitForURL(new RegExp(DECCAN)); await settle(page);
