  { id: "edge1_url_missing", act: async () => {
    await both(line(0), (async () => {
      await goto(`${BASE}/w/${MISSING}`);
      await caption("Address bar: localhost:3000/w/" + MISSING + "\nA workspace ID that does not exist — same response");
    })());
    await line(1); await line(2);
