  { id: "edge1_body_missing", act: async () => {
    await both(line(0), (async () => {
      await type(vehicleForm().locator("input[name=name]"), "Forged vehicle");
      await type(vehicleForm().locator("input[name=registration]"), "FAKE 002");
      await vehicleForm().locator("input[name=workspaceId]").evaluate((el, v) => (el.value = v), MISSING);
      await caption(`DevTools edit: workspaceId value="${MISSING}"\n(a workspace that does not exist)`);
