    const cmd = (ws, note) => `curl "$SUPABASE_URL/rest/v1/projects?workspace_id=eq.${ws}&select=name" -H "Authorization: Bearer $OWNER_TOKEN"   # ${note}`;
    await both(line(0), block({ cmd: "OWNER_TOKEN=$(sign in as owner@fleet.test)   # Deccan Logistics member only", out: "(access token stored)", color: "#9aa5b1" }));
    await line(1);
    await both(line(2), block({ cmd: cmd(DECCAN, "own workspace"), out: clip.data.own, color: "#addb67" }));
    await line(3);
    await both(line(4), block({ cmd: cmd(CHARMINAR, "Charminar Cabs, exists"), out: clip.data.other, color: "#ffcb6b" }));
    await line(5);
    await both(line(6), block({ cmd: cmd(MISSING, "does not exist"), out: clip.data.missing, color: "#ffcb6b" }));
