      out: sh("sed -n '/create function public.has_workspace_role/,/^\\$\\$;/p' supabase/migrations/*initial_schema.sql"), color: "#d6deeb" }));
    await both(line(4), block({ cmd: "grep -n 'as restrictive' -B1 supabase/migrations/*initial_schema.sql | grep projects_scope",
