    await line(5);
  } },
  { id: "edge2_note", prep: async () => { await goto(`${BASE}/w/${DECCAN}/p/${TATA}`); await caption(""); }, act: async () => {
    await line(0); await line(1);
    await both(line(2), highlight(page.locator("text=Brakes making noise").first(), 3500));
    await both(line(3), highlight(page.locator("text=Ignore previous instructions").first(), 3500));
