  const factor = wall / ffprobeDuration(s.video);
  const inputs = ["-i", s.video];
  const af = [];
  s.lines.forEach((l, k) => {
    inputs.push("-i", l.file);
    const ms = Math.max(0, Math.round(l.at - trim * 1000));
    af.push(`[${k + 1}:a]aresample=48000,adelay=${ms}|${ms}[a${k}]`);
  });
